    # Rays run from the pair toward the interior; markers become 4.
    pairs = []
    for c in range(w - 1):
        if g[0][c] == g[0][c+1] == 2:
            pairs.append((0, c, 1, 0))
        if g[h-1][c] == g[h-1][c+1] == 2:
            pairs.append((h-1, c, -1, 0))
    for r in range(h - 1):
        if g[r][0] == g[r+1][0] == 2:
            pairs.append((r, 0, 0, 1))
        if g[r][w-1] == g[r+1][w-1] == 2:
            pairs.append((r, w-1, 0, -1))

    for r, c, color in marks:
        g[r][c] = 4
        for pr, pc, dr, dc in pairs:
            # Only draw ray if marker lies on its line.
            if dr == 0 and r == pr:
                start = pc + dc
                cc = start
                while 0 <= cc < w:
                    if g[r][cc] == bg:
                        g[r][cc] = color
                    cc += dc
            elif dc == 0 and c == pc:
                rr = pr + dr
                while 0 <= rr < h:
                    if g[rr][c] == bg:
                        g[rr][c] = color
                    rr += dr
    return g
